    internal CalibratorHud(){FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;TopMost=true;BackColor=Color.Black;AutoSize=true;AutoSizeMode=AutoSizeMode.GrowAndShrink;Controls.Add(label);}
