    void BeginSession(){session=Path.Combine(pairRoot,order.Index==0?"01-Uncrashed":"02-Cyberpunk");Directory.CreateDirectory(session);sequence=new CalibratorSequence(pairedSettings);clips.Clear();log=new StreamWriter(new FileStream(Path.Combine(session,"commands.csv"),FileMode.CreateNew,FileAccess.Write,FileShare.Read),new UTF8Encoding(false));log.WriteLine("clock_seconds,event,state,clip,physical_throttle,physical_yaw,physical_roll,physical_pitch,sent_throttle,sent_yaw,sent_roll,sent_pitch");CalibratorRuntime.WriteJson(Path.Combine(session,"session.json"),new{Version=CalibratorRuntime.Version,Created=DateTimeOffset.Now.ToString("o"),Game=targetName,GameOrder=order.Index,PID=targetPid,Settings=pairedSettings,VideoFPS=30,Audio=false,CenterCrop=new{Width=960,Height=540},Input="DualSense physical to ViGEm Xbox360",StickDirections=new{ThrottlePositive="Left stick up",YawPositive="Left stick right",RollPositive="Right stick right",PitchPositive="Right stick up; expected nose up by user calibration"},SavedCyberpunkProfile=SavedProfile(),YawReferenceFromUser=new{MaxRate=870,Expo=0.0,Center=250},Limits=new[]{"Impact and altitude are not detected automatically","Initial zero throttle for1s does not guarantee landing or leveling","Uncrashed starts live; Cyberpunk must start in its root Esc pause menu","Automatic switch sends Esc to pauseUncrashed and Esc to resumeCyberpunk","Center crop may omit horizon; verify F6 before testing","Commands sent are not game telemetry"}});sequence.Start(clock.Elapsed.TotalSeconds);lastState="";output.Text=pairRoot;Event("session.start",last,new ControlSample());status.Text=sequence.Status;}
