    void Confirm(){if(sequence==null)throw new IOException("Inicie a série com F10 primeiro.");if(pad==null||!pad.Connected)throw new IOException("DualSense desconectado.");if(sequence.State!="Waiting"&&sequence.State!="RunningVertical")return;if(!CalibratorWindows.Focused(target,targetPid))CalibratorWindows.SetForegroundWindow(target);if(!CalibratorWindows.Focused(target,targetPid))throw new IOException("Use F10 com o jogo escolhido em primeiro plano.");manualInput=false;SendReport(new ControlSample());last=pad.ReadPhysical();sequence.Confirm(clock.Elapsed.TotalSeconds,last);Event("confirm",last,new ControlSample());}
    void Poll(){if(working||closing||handoff)return;working=true;try{if(pad==null)return;if(!pad.Connected){pad.DisconnectVirtual();if(sequence!=null&&(sequence.Recording||sequence.State=="Preparing"))Stop("Controle físico desconectado.");return;}last=pad.ReadPhysical();ControlSample sent=manualInput?last.Copy():new ControlSample();bool focused=CalibratorWindows.Focused(target,targetPid);if(sequence!=null){if(clip!=null&&!focused)sequence.Abort("Jogo perdeu o foco durante a captura.");var automatic=sequence.Tick(clock.Elapsed.TotalSeconds,last,focused);if(!manualInput)sent=automatic;}
        // Release overrides before any recording finalization or disk I/O can block.
        if(pad.VirtualConnected)SendReport(sent);if(sequence!=null){bool captureNow=sequence.Recording||(sequence.State=="Preparing"&&focused);if(captureNow&&clip==null)StartClip();if(!captureNow&&clip!=null)EndClip();if(sequence.State!=lastState){if(sequence.State=="Waiting"&&lastState.StartsWith("Running",StringComparison.Ordinal))System.Media.SystemSounds.Asterisk.Play();lastState=sequence.State;Event("state",last,sent);}if(sequence.Complete||sequence.State=="Aborted"){if(clip!=null)EndClip();CloseLog();if(sequence.Complete){FinishGame();if(order.Finished){if(focused)hud.UpdateFor(target,status.Text);else hud.Hide();}return;}}if(clip!=null&&clip.Error!=null)throw new IOException(clip.Error);status.Text="Etapa "+sequence.StepIndex+"/"+sequence.StepCount+": "+sequence.Status+(manualInput?" MANUAL ativo.":" Potência automática/zero.");}
        if(focused&&sequence!=null&&!sequence.Complete&&sequence.State!="Aborted")hud.UpdateFor(target,status.Text);else hud.Hide();
        if(clip!=null)clip.Label(targetName+" | "+sequence.ClipName+" | "+sequence.Status+" | "+AxisText(sent));if(log!=null&&clock.Elapsed.TotalSeconds-lastLog>=.01){Event("sample",last,sent);lastLog=clock.Elapsed.TotalSeconds;}if(++ticks%12==0)axes.Text=AxisText(last)+"  | Virtual: "+(pad.VirtualConnected?"conectado":"desconectado");}
        catch(Exception ex){Fail(ex);}finally{working=false;}}
    static string AxisText(ControlSample a){return String.Format(CultureInfo.InvariantCulture,"Aceleração {0:P0} · Yaw {1:F2} · Roll {2:F2} · Pitch {3:F2}",a.Throttle,a.Yaw,a.Roll,a.Pitch);}
    void StartClip(){clipName=sequence.ClipName;string directory=Path.Combine(session,clipName);clip=new CalibratorClip(directory,target,targetPid,clock);clips.Add(clipName);Event("record.start",last,lastSent);}
    void EndClip(){var current=clip;clip=null;if(current==null)return;current.Dispose();Event("record.stop",last,lastSent);CalibratorRuntime.WriteJson(Path.Combine(session,clipName,"capture.json"),new{StartedClockSeconds=current.StartedClockSeconds,Frames=current.Frames,DuplicatedFrames=current.Duplicates,Error=current.Error,Game=targetName,Clip=clipName,Finished=DateTimeOffset.Now.ToString("o")});if(current.Error!=null)throw new IOException("Falha na gravação: "+current.Error);}
    void Event(string kind,ControlSample physical,ControlSample sent){if(log==null)return;log.WriteLine(String.Join(",",new[]{clock.Elapsed.TotalSeconds.ToString("F6",CultureInfo.InvariantCulture),kind,sequence==null?"":sequence.State,kind.StartsWith("record.",StringComparison.Ordinal)?clipName:sequence==null?"":sequence.ClipName,physical.Throttle.ToString("R",CultureInfo.InvariantCulture),physical.Yaw.ToString("R",CultureInfo.InvariantCulture),physical.Roll.ToString("R",CultureInfo.InvariantCulture),physical.Pitch.ToString("R",CultureInfo.InvariantCulture),sent.Throttle.ToString("R",CultureInfo.InvariantCulture),sent.Yaw.ToString("R",CultureInfo.InvariantCulture),sent.Roll.ToString("R",CultureInfo.InvariantCulture),sent.Pitch.ToString("R",CultureInfo.InvariantCulture)}));log.Flush();}
    void Stop(string reason){if(sequence!=null)sequence.Abort(reason);manualInput=false;hud.Hide();if(pad!=null&&pad.VirtualConnected){if(pad.Connected)SendReport(new ControlSample());else pad.DisconnectVirtual();}try{EndClip();}finally{CloseLog();}status.Text=reason+" Potência bloqueada em zero. F4 libera o controle físico com stick no mínimo.";}
    void CloseLog(){if(log==null)return;log.Dispose();log=null;}
    void Fail(Exception ex){try{Stop(ex.Message);}catch{}status.Text=ex.Message;}
    void Photo(){ChooseForeground();if(!CalibratorWindows.Focused(target,targetPid))throw new IOException("Use F6 no jogo para conferir o recorte.");string folder=NewFolder(targetName+"-foto");using(var frame=CalibratorWindows.Frame(target,targetPid))frame.Save(Path.Combine(folder,"teste.png"),ImageFormat.Png);output.Text=folder;status.Text="Foto salva. Confira se a imagem do jogo aparece antes de iniciar os testes.";}
    static string RootFolder(){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"FPV Calibrador");}
    static string NewFolder(string name){string root=Path.Combine(RootFolder(),DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+name+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(root);return root;}
    void OpenFolder(){string root=RootFolder();Directory.CreateDirectory(root);Process.Start(new ProcessStartInfo{FileName=root,UseShellExecute=true});}
    static object SavedProfile(){try{string root=@"C:\Program Files (x86)\Steam\steamapps\common\Cyberpunk 2077\bin\x64\plugins\cyber_engine_tweaks\mods\FPVDrone";var index=CalibratorRuntime.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"FPVDrone_Profiles.json")));string path=Path.GetFullPath(Path.Combine(root,Convert.ToString(index["activePath"])));if(!path.StartsWith(root+"\\profiles\\",StringComparison.OrdinalIgnoreCase)||!path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)||new FileInfo(path).Length>262144)return null;var data=CalibratorRuntime.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var physics=(Dictionary<string,object>)data["physics"];var controls=(Dictionary<string,object>)data["controls"];var camera=(Dictionary<string,object>)data["camera"];return new{Profile=Path.GetFileName(path),Rates=controls["actualRates"],Gravity=physics["gravity"],Mass=physics["massGrams"],MotorReference=((Dictionary<string,object>)physics["powerSystem"])["referenceThrustToWeightRatio"],CameraAngle=camera["angle"],CameraFov=camera["horizontalFOV"],SavedOnly=true};}catch{return null;}}
    void Help(){using(var form=new Form{Text="Como usar e licenças",Width=820,Height=650,StartPosition=FormStartPosition.CenterParent}){var text=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text="PREPARAÇÃO ÚNICA\r\n1. Pause ambos; Ler DualSense e Conectar virtual. A potência fica em zero.\r\n2. Stick esquerdo no mínimo + F4 libera manual. Escolha e calibre o Xbox virtual em cada jogo, conferindo amplitudes e direção. F5 bloqueia zero novamente. Sem L1 automático; deixe os drones prontos manualmente.\r\n3. Use Acro e comece perto do chão/nivelado. Deixe Uncrashed pronto para voar, e Cyberpunk na pausa principal de Esc. Marque a confirmação. F6 no jogo salva prévia central960×540; use janela sem bordas se ficar preta.\r\n\r\nENSAIO COM F10\r\n4. F10 foca Uncrashed, mantém0por1s e executa primeira etapa. Na vertical, F10 depois do impacto finaliza o trecho.\r\n5. Entre etapas não grava. Reposicione/reset conforme necessário; F4 permite manual com stick no mínimo, F5 volta a zero. F10 continua.\r\n6. Ao concluir Uncrashed, o app envia Esc para pausá-lo; focaCyberpunk e envia Esc para retomá-lo. O drone do CP deve ter sido deixado pronto/pausado; não há reconhecimento de menu. A primeira etapa CP inicia e o mesmo fluxo repete.\r\n7. F12 para imediatamente em potência zero. Se perder foco ou desconectar controle, a etapa é interrompida.\r\n8. Envie a pasta da série em Documentos > FPV Calibrador, com AVI/CSV/JSON. São comandos enviados; não há medição automática de gravidade/pouso.\r\n\r\nMAPEAMENTO\r\nEsquerdo cima=acelerar, direita=yawdireita. Direito direita=roll; direito cima=narizparacima conforme sua calibração. Confirme esse efeito nos dois jogos.\r\n\r\n"+CalibratorRuntime.Notices()};form.Controls.Add(text);form.ShowDialog(this);}}
}

internal static class CalibratorProgram {
    [STAThread]static int Main(string[] args){CalibratorWindows.Dpi();try{
        if(args.Length==2&&args[0]=="--self-test"){Directory.CreateDirectory(args[1]);int capture=CalibratorCapture.SelfTest(Path.Combine(args[1],"capture"));int sequence=CalibratorSequence.SelfTest(),gamepad=CalibratorGamepad.SelfTest();bool targets=CalibratorWindows.Allowed("Cyberpunk2077")&&CalibratorWindows.Allowed("Uncrashed-Win64-Shipping")&&!CalibratorWindows.Allowed("explorer");if(!targets)throw new Exception("Filtro de alvo falhou");int gameOrder=CalibratorGameOrder.SelfTest();Size size=CalibratorWindows.VideoSize(new Rectangle(0,0,3440,1440));if(size.Width!=1280||size.Height!=534)throw new Exception("Proporção de captura falhou");var crop=CalibratorWindows.CenterCrop(new Rectangle(0,0,3440,1440));if(crop!=new Rectangle(1240,450,960,540))throw new Exception("Recorte central falhou");if(CalibratorWindows.CenterCrop(new Rectangle(0,0,640,360))!=new Rectangle(0,0,640,360))throw new Exception("Recorte menor falhou");if(CalibratorWindows.CenterCrop(new Rectangle(-1920,0,1920,1080))!=new Rectangle(-1440,270,960,540))throw new Exception("Recorte em outro monitor falhou");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var window=new CalibratorWindow(true)){window.ShowInTaskbar=false;window.StartPosition=FormStartPosition.Manual;window.Location=new System.Drawing.Point(-30000,-30000);int policy=window.PolicySelfTest();if(policy!=2)throw new Exception("Política de potência falhou");window.Show();Application.DoEvents();using(var bitmap=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(bitmap,new Rectangle(0,0,window.Width,window.Height));bitmap.Save(Path.Combine(args[1],"interface.png"),ImageFormat.Png);}window.Close();}CalibratorRuntime.WriteJson(Path.Combine(args[1],"resultado.json"),new{Passed=capture+sequence+gamepad+8+gameOrder,GameOrder=gameOrder,Capture=capture,Sequence=sequence,Gamepad=gamepad,RuntimeHardwareUsed=false,VirtualCreated=false,GameTouched=false,PreviewOnly=true});return 0;}
        if(args.Length==2&&args[0]=="--probe-physical"){using(var pad=CalibratorRuntime.Gamepad()){pad.OpenPhysical();var value=pad.ReadPhysical();CalibratorRuntime.WriteJson(args[1],new{PhysicalName=pad.PhysicalName,Connected=pad.Connected,Throttle=value.Throttle,Yaw=value.Yaw,Roll=value.Roll,Pitch=value.Pitch,VirtualCreated=pad.VirtualConnected,DriverInstalled=false,GameFilesChanged=false});}return 0;}
        if(args.Length==2&&args[0]=="--probe-bus"){using(var pad=CalibratorRuntime.Gamepad()){pad.ProbeBusOnly();CalibratorRuntime.WriteJson(args[1],new{DriverResponded=true,VirtualCreated=pad.VirtualConnected,ControllerInputSent=false,GameFilesChanged=false});}return 0;}
        if(args.Length==2&&args[0]=="--probe-windows"){var windows=new List<object>();for(int game=0;game<2;game++){IntPtr w=CalibratorWindows.FindGame(game);Rectangle area=CalibratorWindows.Area(w);windows.Add(new{Game=game==0?"Uncrashed":"Cyberpunk",PID=CalibratorWindows.Pid(w),Width=area.Width,Height=area.Height});}CalibratorRuntime.WriteJson(args[1],new{Windows=windows,FocusChanged=false,InputSent=false,ScreenshotTaken=false});return 0;}
        if(args.Length!=0)throw new IOException("Argumento não reconhecido.");bool created;using(var mutex=new Mutex(true,"Local\\FPVCalibradorApp",out created)){if(!created){MessageBox.Show("O calibrador já está aberto.");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new CalibratorWindow());}return 0;
    }catch(Exception ex){if(args.Length>1){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[1])));File.WriteAllText(args[1]+".error.txt",ex.ToString());}else MessageBox.Show(ex.Message,"Calibrador FPV");return 1;}}
}
